mkdir -p cap
cat > collect.mjs <<'EOF'
import { chromium } from 'playwright';

const url = process.argv[2];
const label = process.argv[3] || 'run';
const captures = [];

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ userAgent:
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36' });

page.on('response', async (resp) => {
  try {
    const req = resp.request();
    const u = resp.url();
    const ct = (resp.headers()['content-type'] || '');
    // keep API-ish traffic: campspot, server actions (POST to page), json / flight
    const interesting =
      /campspot\.com/i.test(u) ||
      (req.method() === 'POST' && /book\.campfimfo\.com/i.test(u)) ||
      /json|x-component|text\/plain/i.test(ct);
    if (!interesting) return;
    let body = '';
    try { body = await resp.text(); } catch {}
    if (!body) return;
    if (!/avail|campsite|siteType|siteCategory|"rate"|nightly|price|soldOut/i.test(body)) return;
    captures.push({ method: req.method(), url: u, status: resp.status(), ct, len: body.length, body });
  } catch {}
});

await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 45000 }).catch(()=>{});
// let client-side availability calls fire
await page.waitForTimeout(9000);
// nudge: some builds require a visible interaction to trigger search
try { await page.getByRole('button', { name: /search|find|update/i }).first().click({ timeout: 3000 }); } catch {}
await page.waitForTimeout(6000);

await browser.close();

console.log(`captured ${captures.length} candidate responses`);
captures.sort((a,b)=>b.len-a.len);
let i=0;
for (const c of captures) {
  const f = `cap/${label}_${i}_${c.method}_${c.status}.txt`;
  const fs = await import('fs');
  fs.writeFileSync(f, `URL: ${c.url}\nMETHOD: ${c.method}\nSTATUS: ${c.status}\nCT: ${c.ct}\nLEN: ${c.len}\n\n${c.body}`);
  console.log(`  [${i}] ${c.method} ${c.status} len=${c.len} ${c.ct.split(';')[0]}  ${c.url.slice(0,90)}`);
  i++;
}
EOF
export NODE_PATH="$(npm root -g)"
node collect.mjs "https://book.campfimfo.com/waco/search?checkin=2026-08-07&checkout=2026-08-09&guests=2" waco_aug 2>&1 | head -30

