# -*- coding: utf-8 -*-
# HTML report template for waco_monitor.py.
# The literal  /*__PAYLOAD__*/ null  is replaced with the JSON data payload.

TEMPLATE = r"""<title>Camp Fimfo Waco - Summer Booking-Pace Monitor</title>
<style>
  :root {
    --ground:#f6f7f5; --surface:#fff; --surface-2:#f0f2ee;
    --ink:#1b2420; --muted:#5c6660; --faint:#8a938d; --line:#e0e3dd;
    --waco:#2f6b4d; --hc:#b8862f; --gap:#c2560f; --good:#2f6b4d; --warn:#c2560f;
    --shadow:0 1px 2px rgba(27,36,32,.06),0 8px 24px rgba(27,36,32,.05);
    --serif:"Iowan Old Style",Georgia,"Times New Roman",serif;
    --sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  }
  @media (prefers-color-scheme:dark){:root{
    --ground:#131714;--surface:#1a201c;--surface-2:#212824;--ink:#eef2ef;--muted:#a4aea7;
    --faint:#79837c;--line:#2c332e;--waco:#5fb387;--hc:#d9ab52;--gap:#f0803f;--good:#5fb387;--warn:#f0803f;
    --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35);}}
  :root[data-theme="light"]{--ground:#f6f7f5;--surface:#fff;--surface-2:#f0f2ee;--ink:#1b2420;--muted:#5c6660;
    --faint:#8a938d;--line:#e0e3dd;--waco:#2f6b4d;--hc:#b8862f;--gap:#c2560f;--good:#2f6b4d;--warn:#c2560f;
    --shadow:0 1px 2px rgba(27,36,32,.06),0 8px 24px rgba(27,36,32,.05);}
  :root[data-theme="dark"]{--ground:#131714;--surface:#1a201c;--surface-2:#212824;--ink:#eef2ef;--muted:#a4aea7;
    --faint:#79837c;--line:#2c332e;--waco:#5fb387;--hc:#d9ab52;--gap:#f0803f;--good:#5fb387;--warn:#f0803f;
    --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35);}

  *{box-sizing:border-box}
  body{margin:0;background:var(--ground);color:var(--ink);font-family:var(--sans);line-height:1.55;
    -webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums}
  .wrap{max-width:920px;margin:0 auto;padding:clamp(24px,5vw,64px) clamp(18px,5vw,40px) 80px}
  .eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--faint);font-weight:600;margin:0 0 14px}
  h1{font-family:var(--serif);font-weight:600;letter-spacing:-.01em;font-size:clamp(30px,5.5vw,46px);
    line-height:1.08;margin:0 0 16px;text-wrap:balance}
  .dek{font-size:clamp(16px,2.4vw,19px);color:var(--muted);max-width:62ch;margin:0 0 22px}
  .meta{display:flex;flex-wrap:wrap;gap:10px 22px;align-items:center;padding-top:18px;border-top:1px solid var(--line);
    font-size:13px;color:var(--muted)}
  .meta b{color:var(--ink);font-weight:600}
  .verdict{display:inline-flex;align-items:center;gap:8px;padding:5px 12px;border-radius:999px;font-size:12.5px;
    font-weight:600;letter-spacing:.01em;
    background:color-mix(in srgb,var(--warn) 12%,var(--surface));color:var(--warn);
    border:1px solid color-mix(in srgb,var(--warn) 30%,transparent)}
  .verdict.ok{background:color-mix(in srgb,var(--good) 12%,var(--surface));color:var(--good);
    border-color:color-mix(in srgb,var(--good) 30%,transparent)}
  .verdict .dot{width:7px;height:7px;border-radius:50%;background:currentColor}

  section{margin-top:clamp(38px,6vw,58px)}
  h2{font-family:var(--serif);font-weight:600;font-size:clamp(20px,3vw,26px);letter-spacing:-.01em;margin:0 0 6px}
  .sub{color:var(--muted);font-size:14.5px;margin:0 0 20px;max-width:68ch}

  .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
  @media (max-width:680px){.stats{grid-template-columns:repeat(2,1fr)}}
  .stat{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px 16px;box-shadow:var(--shadow)}
  .stat .k{font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:var(--faint);font-weight:600;margin-bottom:10px}
  .stat .v{font-family:var(--serif);font-size:30px;font-weight:600;line-height:1;letter-spacing:-.02em}
  .stat .v small{font-size:15px;font-family:var(--sans);color:var(--muted);font-weight:500}
  .stat .note{font-size:12.5px;color:var(--muted);margin-top:9px}
  .v.warn{color:var(--warn)} .v.good{color:var(--good)}

  .card{background:var(--surface);border:1px solid var(--line);border-radius:14px;
    padding:22px clamp(14px,3vw,26px) 18px;box-shadow:var(--shadow)}
  .legend{display:flex;flex-wrap:wrap;gap:18px;font-size:13px;color:var(--muted);margin-bottom:6px}
  .legend span{display:inline-flex;align-items:center;gap:7px}
  .swatch{width:22px;height:3px;border-radius:2px;display:inline-block}
  #chart{width:100%;height:auto;display:block}
  .chart-cap{font-size:12.5px;color:var(--faint);margin-top:12px;text-align:center}

  .twrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:var(--shadow)}
  table{border-collapse:collapse;width:100%;font-size:13.5px;min-width:620px}
  thead th{text-align:right;font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--faint);
    font-weight:600;padding:14px 14px 10px;border-bottom:1px solid var(--line);white-space:nowrap}
  thead th:first-child,tbody td:first-child{text-align:left}
  tbody td{padding:11px 14px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}
  tbody tr:last-child td{border-bottom:none}
  tbody tr.near{background:color-mix(in srgb,var(--warn) 5%,transparent)}
  .arr{font-weight:600;color:var(--ink)} .tag{display:block;font-size:11.5px;color:var(--faint);font-weight:400}
  .gapcell{font-weight:600} .gapcell.behind{color:var(--gap)} .gapcell.flat{color:var(--muted)}
  .blocked td{color:var(--muted);font-style:italic;text-align:left;background:var(--surface-2)}

  .pacegrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px}
  .pcard{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:15px 16px 12px;box-shadow:var(--shadow)}
  .pcard .ph{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}
  .pcard .pa{font-family:var(--serif);font-size:17px;font-weight:600}
  .pcard .pd{font-size:11px;color:var(--faint);letter-spacing:.03em;text-transform:uppercase}
  .pcard svg{width:100%;height:56px;display:block;margin:2px 0 8px}
  .pcard .pv{display:flex;gap:14px;font-size:12.5px}
  .pcard .pv b{font-family:var(--serif);font-size:16px} .pcard .pv .lp{color:var(--muted);font-weight:500}
  .empty{background:var(--surface-2);border:1px dashed var(--line);border-radius:12px;padding:26px;
    text-align:center;color:var(--muted);font-size:14px}
  .empty b{color:var(--ink)}

  .findings{display:grid;gap:12px;margin:4px 0 0;padding:0;list-style:none}
  .findings li{background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent,var(--waco));
    border-radius:10px;padding:15px 17px;box-shadow:var(--shadow)}
  .findings li.pos{--accent:var(--good)} .findings li.neg{--accent:var(--gap)} .findings li.neu{--accent:var(--hc)}
  .findings .lead{font-weight:600;display:block;margin-bottom:3px}
  .findings .body{color:var(--muted);font-size:14px}

  .caveats{display:grid;gap:10px;grid-template-columns:1fr 1fr}
  @media (max-width:680px){.caveats{grid-template-columns:1fr}}
  .caveats .c{font-size:13.5px;color:var(--muted);padding-left:16px;position:relative}
  .caveats .c::before{content:"";position:absolute;left:0;top:9px;width:6px;height:6px;border-radius:50%;background:var(--faint)}
  .caveats .c b{color:var(--ink);font-weight:600}

  footer{margin-top:56px;padding-top:20px;border-top:1px solid var(--line);font-size:12.5px;color:var(--faint);line-height:1.6}
  footer code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;color:var(--muted);
    background:var(--surface-2);padding:1px 5px;border-radius:4px}
</style>

<div class="wrap">
  <header>
    <p class="eyebrow">Wake Robin - Portfolio Monitoring - Booking-Pace Monitor</p>
    <h1 id="headline">Camp Fimfo Waco summer booking pace</h1>
    <p class="dek">Forward summer demand for the Waco resort, read directly from the property's live
      reservation system and benchmarked against Camp Fimfo Texas Hill Country - same operator, same
      booking platform - as a control. Updated weekly; the pace curve builds with each run.</p>
    <div class="meta" id="meta"></div>
  </header>

  <section><div class="stats" id="stats"></div></section>

  <section>
    <h2>Latest snapshot - booking pace by lead time</h2>
    <p class="sub">Share of bookable sites already reserved, by arrival weekend. Far-out dates sit near
      empty for both parks - that's normal lead time, not signal. The story is the shaded gap on the
      near-in weekends.</p>
    <div class="card">
      <div class="legend">
        <span><i class="swatch" style="background:var(--waco)"></i> Waco (the investment)</span>
        <span><i class="swatch" style="background:var(--hc)"></i> Texas Hill Country (control)</span>
        <span><i class="swatch" style="background:var(--gap);opacity:.35"></i> pace gap</span>
      </div>
      <svg id="chart" viewBox="0 0 760 340" role="img" aria-label="Occupancy by arrival weekend"></svg>
      <p class="chart-cap" id="chartcap"></p>
    </div>
  </section>

  <section>
    <h2>The full comparison</h2>
    <p class="sub">Percent booked and median advertised nightly rate (2 adults) by arrival. Highlighted
      rows are the near-in weekends that carry the demand signal.</p>
    <div class="twrap"><table>
      <thead><tr>
        <th>Arrival</th><th>Lead</th><th>Waco booked</th><th>Waco $/night</th>
        <th>Hill Cty booked</th><th>Hill Cty $/night</th><th>Gap</th>
      </tr></thead><tbody id="tbody"></tbody>
    </table></div>
  </section>

  <section>
    <h2>Booking pace over time</h2>
    <p class="sub" id="pacesub">How each summer weekend has filled across weekly observations. A steep
      climb is healthy pickup; a flat line as the date nears is stalling demand.</p>
    <div id="pacewrap"></div>
  </section>

  <section>
    <h2>How much to lean on this</h2>
    <div class="caveats">
      <div class="c"><b>Pace &gt; snapshot.</b> A single observation is a baseline; the signal is whether
        Waco's near-in weekends compress week over week. That view fills in above as runs accumulate.</div>
      <div class="c"><b>Availability != occupancy.</b> Owner blocks, holds and channel allocation aren't
        visible. The Waco-vs-control framing cancels most methodology bias.</div>
      <div class="c"><b>Inventory denominator is a proxy.</b> Total sites estimated from off-season
        availability; if anything this understates Hill Country peak inventory, making the gap conservative.</div>
      <div class="c"><b>Public rate, not realized ADR.</b> Advertised nightly rate is the yield-system ask,
        not booked revenue. As an investor you can request first-party occupancy for ground truth.</div>
    </div>
  </section>

  <footer id="footer"></footer>
</div>

<script>
const PAYLOAD = /*__PAYLOAD__*/ null;
const P = PAYLOAD;
const css = getComputedStyle(document.documentElement);
const col = k => css.getPropertyValue(k).trim();
const NS = "http://www.w3.org/2000/svg";
const el = (t,a)=>{const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);return e;};

/* ---------- derived headline / verdict ---------- */
const wknd = P.snapshot.filter(d=>d.wk && !d.holiday && !d.blocked);
const near = wknd.filter(d=>d.lead<=28);
const nearGap = near.length ? Math.round(near.reduce((s,d)=>s+(d.w-d.h),0)/near.length) : 0;
const nearest = wknd[0] || null;
const discounts = P.snapshot.reduce((s,d)=>s+d.wdisc+d.hdisc,0);
const behind = nearGap <= -10;
document.getElementById('headline').textContent = behind
  ? "Camp Fimfo Waco is pacing behind its sister park on near-term summer weekends"
  : "Camp Fimfo Waco summer booking pace is tracking its sister park";

/* ---------- meta ---------- */
const verdictTxt = behind
  ? (discounts? "Behind pace, discounting" : "Soft volume, holding price")
  : "In line with control";
document.getElementById('meta').innerHTML =
  `<span class="verdict ${behind?'':'ok'}"><span class="dot"></span>${verdictTxt}</span>`+
  `<span>Observed <b>${P.latestFull}</b></span>`+
  `<span>Weekly runs so far <b>${P.nObs}</b></span>`+
  `<span>Source <b>Campspot reservation API</b></span>`;

/* ---------- stats ---------- */
const statCards = [];
if(nearest){
  statCards.push({k:`Nearest wknd - Waco`, v:nearest.w, unit:'% booked', cls:'', note:`${nearest.arr}, +${nearest.lead}d lead`});
  statCards.push({k:`Nearest wknd - Hill Cty`, v:nearest.h, unit:'% booked', cls:nearest.h>=85?'warn':'', note:nearest.h>=95?'Effectively sold out':'Control'});
}
statCards.push({k:'Near-in pace gap', v:(nearGap>0?'+':'')+nearGap, unit:'pts', cls:behind?'warn':'', note:'Waco vs control, <=4wk out'});
statCards.push({k:'Promo discounts', v:discounts, unit:'', cls:discounts?'warn':'good', note:discounts?'Markdowns present':'No markdowns anywhere'});
document.getElementById('stats').innerHTML = statCards.map(s=>
  `<div class="stat"><div class="k">${s.k}</div><div class="v ${s.cls}">${s.v}<small>${s.unit}</small></div>`+
  `<div class="note">${s.note}</div></div>`).join('');

/* ---------- table ---------- */
const tb=document.getElementById('tbody');
P.snapshot.forEach(d=>{
  if(d.blocked){
    const tr=document.createElement('tr');tr.className='blocked';
    tr.innerHTML=`<td colspan="7">${d.arr} - 2-night search returns nothing at both parks: minimum-stay enforced (a normal compression signal).</td>`;
    tb.appendChild(tr);return;
  }
  const gap=d.w-d.h, isNear=d.wk&&d.lead<=28&&!d.holiday;
  const gcls=Math.abs(gap)<=4?'flat':(gap<0?'behind':'flat');
  const tr=document.createElement('tr'); if(isNear)tr.className='near';
  tr.innerHTML=`<td><span class="arr">${d.arr}</span><span class="tag">${d.tag}</span></td>`+
    `<td>${d.lead}d</td><td>${d.w}%</td><td>$${d.wm}</td><td>${d.h}%</td><td>$${d.hm}</td>`+
    `<td class="gapcell ${gcls}">${(gap>0?'+':'')+gap} pts</td>`;
  tb.appendChild(tr);
});

/* ---------- lead-time chart (latest snapshot, weekends) ---------- */
(function(){
  const pts=P.snapshot.filter(d=>d.wk&&!d.holiday&&d.lead<=49&&!d.blocked);
  const svg=document.getElementById('chart');
  document.getElementById('chartcap').textContent =
    `Weekend (2-night) arrivals. Occupancy = 1 - open sites / off-season baseline (Waco ~${P.baselines.Waco}, Hill Cty ~${P.baselines.HillCountry} sites).`;
  if(pts.length<2){svg.remove();return;}
  const W=760,H=340,m={t:20,r:20,b:52,l:44},iw=W-m.l-m.r,ih=H-m.t-m.b,n=pts.length;
  const x=i=>m.l+iw*i/(n-1), y=v=>m.t+ih*(1-v/100);
  [0,25,50,75,100].forEach(v=>{
    svg.appendChild(el('line',{x1:m.l,x2:W-m.r,y1:y(v),y2:y(v),stroke:col('--line'),'stroke-width':1}));
    const t=el('text',{x:m.l-10,y:y(v)+4,'text-anchor':'end','font-size':11,fill:col('--faint')});t.textContent=v+'%';svg.appendChild(t);
  });
  const pth=k=>pts.map((d,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(d[k]).toFixed(1)).join(' ');
  const area=pts.map((d,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(d.w).toFixed(1)).join(' ')+' '+
    pts.slice().reverse().map((d,i)=>'L'+x(n-1-i).toFixed(1)+' '+y(d.h).toFixed(1)).join(' ')+' Z';
  svg.appendChild(el('path',{d:area,fill:col('--gap'),opacity:.14}));
  svg.appendChild(el('path',{d:pth('h'),fill:'none',stroke:col('--hc'),'stroke-width':2.5,'stroke-linejoin':'round','stroke-linecap':'round'}));
  svg.appendChild(el('path',{d:pth('w'),fill:'none',stroke:col('--waco'),'stroke-width':2.5,'stroke-linejoin':'round','stroke-linecap':'round'}));
  pts.forEach((d,i)=>{
    svg.appendChild(el('circle',{cx:x(i),cy:y(d.h),r:3.5,fill:col('--hc')}));
    svg.appendChild(el('circle',{cx:x(i),cy:y(d.w),r:3.5,fill:col('--waco')}));
    const a=el('text',{x:x(i),y:H-32,'text-anchor':'middle','font-size':11,fill:col('--muted')});a.textContent=d.arr;svg.appendChild(a);
    const b=el('text',{x:x(i),y:H-18,'text-anchor':'middle','font-size':9.5,fill:col('--faint')});b.textContent='+'+d.lead+'d';svg.appendChild(b);
  });
  const ann=(i,k,c,dy)=>{const t=el('text',{x:x(i)+8,y:y(pts[i][k])+dy,'font-size':11.5,'font-weight':600,fill:col(c)});t.textContent=pts[i][k]+'%';svg.appendChild(t);};
  ann(0,'h','--hc',-8);ann(0,'w','--waco',16);
})();

/* ---------- pace over time (small multiples) ---------- */
(function(){
  const wrap=document.getElementById('pacewrap');
  const arrivals=Object.keys(P.pace);
  if(P.nObs<2){
    document.getElementById('pacesub').textContent =
      "This view compares weekly observations of the same arrival dates. It activates after the second weekly run.";
    wrap.innerHTML=`<div class="empty">Only <b>${P.nObs}</b> observation so far (baseline set ${P.latestFull}).<br>The booking-pace curve appears here after the next weekly run.</div>`;
    return;
  }
  const grid=document.createElement('div');grid.className='pacegrid';
  arrivals.forEach(arr=>{
    const s=P.pace[arr]; const last=s[s.length-1];
    const w=160,h=56,pad=6,n=s.length;
    const xx=i=>pad+(w-2*pad)*(n===1?0.5:i/(n-1)), yy=v=>pad+(h-2*pad)*(1-v/100);
    const pth=k=>s.map((d,i)=>(i?'L':'M')+xx(i).toFixed(1)+' '+yy(d[k]).toFixed(1)).join(' ');
    let svg=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">`;
    svg+=`<path d="${pth('h')}" fill="none" stroke="${col('--hc')}" stroke-width="2" stroke-linejoin="round"/>`;
    svg+=`<path d="${pth('w')}" fill="none" stroke="${col('--waco')}" stroke-width="2" stroke-linejoin="round"/>`;
    svg+=`<circle cx="${xx(n-1)}" cy="${yy(last.h)}" r="2.6" fill="${col('--hc')}"/>`;
    svg+=`<circle cx="${xx(n-1)}" cy="${yy(last.w)}" r="2.6" fill="${col('--waco')}"/></svg>`;
    const card=document.createElement('div');card.className='pcard';
    card.innerHTML=`<div class="ph"><span class="pa">${arr}</span><span class="pd">${s[0].o} -> ${last.o}</span></div>`+
      svg+
      `<div class="pv"><span><span class="lp">Waco</span> <b style="color:${col('--waco')}">${last.w}%</b></span>`+
      `<span><span class="lp">Hill Cty</span> <b style="color:${col('--hc')}">${last.h}%</b></span></div>`;
    grid.appendChild(card);
  });
  wrap.appendChild(grid);
})();

/* ---------- footer ---------- */
document.getElementById('footer').innerHTML =
  `Method - Availability read live from the Camp Fimfo reservation backend (Campspot park 2264 for Waco, `+
